package com.studentassignment.service;
import com.studentassignment.model.*;import com.studentassignment.repository.*;import java.time.LocalDateTime;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;
import com.studentassignment.api.Views.DashboardView;
@Service public class SubmissionService {
 private final SubmissionRepository submissions;private final AssignmentService assignments;private final UserRepository users;private final FileStorageService files;
 public SubmissionService(SubmissionRepository submissions,AssignmentService assignments,UserRepository users,FileStorageService files){this.submissions=submissions;this.assignments=assignments;this.users=users;this.files=files;}
 public List<Submission> mine(Long student){return submissions.findByStudentIdOrderBySubmittedAtDesc(student);}
 public List<Submission> forAssignment(Long id,Long faculty){assignments.owned(id,faculty);return submissions.findByAssignmentIdOrderBySubmittedAtDesc(id);}
 public Submission get(Long id){return submissions.findById(id).orElseThrow(()->ApiException.notFound("Submission not found."));}
 public boolean mayRead(Long id,Long userId,UserRole role){Submission s=get(id);return role==UserRole.STUDENT?s.getStudent().getId().equals(userId):s.getAssignment().getCreatedBy().getId().equals(userId);}
 @Transactional public Submission upload(Long assignmentId,MultipartFile file,Long studentId){Assignment a=assignments.get(assignmentId);User u=users.findById(studentId).orElseThrow(()->ApiException.notFound("User not found."));validateFile(file);var saved=files.store(file);SubmissionStatus status=a.getDeadline().isBefore(LocalDateTime.now())?SubmissionStatus.LATE:SubmissionStatus.SUBMITTED;var old=submissions.findByAssignmentIdAndStudentId(assignmentId,studentId);if(old.isPresent()){old.get().replaceFile(saved.path(),saved.originalName(),status);return old.get();}return submissions.save(new Submission(a,u,saved.path(),saved.originalName(),status));}
 @Transactional public Submission grade(Long id,int marks,String feedback,Long facultyId){Submission s=get(id);if(!s.getAssignment().getCreatedBy().getId().equals(facultyId))throw ApiException.forbidden();if(marks<0||marks>s.getAssignment().getMaxMarks())throw new ApiException(HttpStatus.BAD_REQUEST,"Marks must be between 0 and the assignment maximum.");s.grade(marks,feedback);return s;}
 public DashboardView dashboard(Long id){return new DashboardView(submissions.countByStudentId(id),submissions.countByStudentIdAndStatus(id,SubmissionStatus.SUBMITTED),submissions.countByStudentIdAndStatus(id,SubmissionStatus.GRADED),submissions.countByStudentIdAndStatus(id,SubmissionStatus.LATE));}
 private void validateFile(MultipartFile f){if(f==null||f.isEmpty())throw new ApiException(HttpStatus.BAD_REQUEST,"Choose a file to upload.");if(f.getSize()>10L*1024*1024)throw new ApiException(HttpStatus.BAD_REQUEST,"File size exceeds 10 MB limit.");String n=f.getOriginalFilename()==null?"":f.getOriginalFilename().toLowerCase(Locale.ROOT);if(!(n.endsWith(".pdf")||n.endsWith(".doc")||n.endsWith(".docx")))throw new ApiException(HttpStatus.BAD_REQUEST,"Only PDF, DOC and DOCX files are accepted.");}
}
